// ActionGet defines model for ActionGet.
type ActionGet struct {
	// Action the action to be executed on recall
	Action ActionGetAction    `json:"action"`
	Target ResourceIdentifier `json:"target"`
}

// ActionGetAction the action to be executed on recall
type ActionGetAction struct {
	// Color Example:
	Color *ActionGetActionColor `json:"color,omitempty"`

	// ColorTemperature Example:
	ColorTemperature *ActionGetActionColorTemperature `json:"color_temperature,omitempty"`

	// Dimming Example:
	Dimming  *ActionGetActionDimming  `json:"dimming,omitempty"`
	Dynamics *ActionGetActionDynamics `json:"dynamics,omitempty"`

	// Effects Deprecated: use effects_v2
	Effects *ActionGetActionEffects `json:"effects,omitempty"`

	// EffectsV2 Basic feature containing effects v2 properties
	EffectsV2 *ActionGetActionEffectsV2 `json:"effects_v2,omitempty"`

	// Gradient Basic feature containing gradient properties.
	Gradient *ActionGetActionGradient `json:"gradient,omitempty"`
	On       *ActionGetActionOn       `json:"on,omitempty"`
}

// ActionGetActionColor Example:
type ActionGetActionColor struct {
	Xy XY `json:"xy"`
}

// ActionGetActionColorTemperature Example:
type ActionGetActionColorTemperature struct {
	// Mirek color temperature in mirek or null when the light color is not in the ct spectrum
	Mirek int `json:"mirek"`
}

// ActionGetActionDimming Example:
type ActionGetActionDimming struct {
	// Brightness Brightness percentage. value cannot be 0, writing 0 changes it to lowest possible brightness
	Brightness float32 `json:"brightness"`
}

// ActionGetActionDynamics defines model for ActionGetActionDynamics.
type ActionGetActionDynamics struct {
	// Duration Duration of a light transition in ms.
	Duration *int `json:"duration,omitempty"`
}

// ActionGetActionEffects Deprecated: use effects_v2
